type ReferenceRenderer = (page: StandalonePage & { pageNum: number }) => React.ReactNode;
const DEFAULT_PAGE_FORMAT = { width: 210, height: 297 };
const useIsoLayoutEffect = typeof window === 'undefined' ? React.useEffect : React.useLayoutEffect;

function getPageFlowKey(page: StandalonePage, parent?: PageItem) {
  return parent ? `${parent.id}/${page.id}` : page.id;
}

// Schema-based page option types
export type PageOptionSelectValue = {
  label: LocalizedText;
  /** Matched to the stored value as a string; a payload option writes it typed by `valueType`. */
  value: string | number | boolean;
  hex?: string; // For color-series options
};

type PageOptionTarget = string | ((pageOrGroup: PageItem) => boolean);

type BasePageOption = {
  id: string;
  label: LocalizedText;
  description?: LocalizedText;
  appliesTo?: PageOptionTarget | PageOptionTarget[];
};

export type SelectPageOption = BasePageOption & {
  type: 'select';
  options: PageOptionSelectValue[];
  getValue: (pageOrGroup: PageItem) => string | number | boolean;
  onChange?: (
    pageOrGroupId: string,
    value: string,
    context: { item?: PageItem; updateItem: (patch: Partial<PageItem>) => void }
  ) => void;
  applyPatch?: (value: string, item?: PageItem) => Partial<PageItem> | void;
};

export type TogglePageOption = BasePageOption & {
  type: 'toggle';
  getValue: (pageOrGroup: PageItem) => boolean;
  onChange?: (
    pageOrGroupId: string,
    value: string,
    context: { item?: PageItem; updateItem: (patch: Partial<PageItem>) => void }
  ) => void;
  applyPatch?: (value: string, item?: PageItem) => Partial<PageItem> | void;
};

export type SliderPageOption = BasePageOption & {
  type: 'slider';
  min: number;
  max: number;
  step: number;
  getValue: (pageOrGroup: PageItem) => number;
  onChange?: (
    pageOrGroupId: string,
    value: string,
    context: { item?: PageItem; updateItem: (patch: Partial<PageItem>) => void }
  ) => void;
  applyPatch?: (value: string, item?: PageItem) => Partial<PageItem> | void;
};

export type CounterPageOption = BasePageOption & {
  type: 'counter';
  min: number;
  max: number;
  step: number;
  getValue: (pageOrGroup: PageItem) => number;
  onChange?: (
    pageOrGroupId: string,
    value: string,
    context: { item?: PageItem; updateItem: (patch: Partial<PageItem>) => void }
  ) => void;
  applyPatch?: (value: string, item?: PageItem) => Partial<PageItem> | void;
};

export type ColorSeriesPageOption = BasePageOption & {
  type: 'color-series';
  options: PageOptionSelectValue[]; // Must include hex property
  getValue: (pageOrGroup: PageItem) => string;
  onChange?: (
    pageOrGroupId: string,
    value: string,
    context: { item?: PageItem; updateItem: (patch: Partial<PageItem>) => void }
  ) => void;
  applyPatch?: (value: string, item?: PageItem) => Partial<PageItem> | void;
};

export type PageOption = SelectPageOption | TogglePageOption | SliderPageOption | CounterPageOption | ColorSeriesPageOption;

type PreviewMode = 'single_page' | 'two_pages';

export interface PageEditorProps {
  templateConfig: Parameters<typeof buildPageGroupsConfig>[0];
  payload?: any;
  onPayloadChange?: (nextPayload: any) => void;
  pageFormat?: { width: number; height: number; preview?: PreviewMode; bleed?: number; [key: string]: any };
  pageOptions?: Array<PageOption | PayloadOptionDefinition>;
  notifyError?: (message: string) => void;
  referenceRenderer?: ReferenceRenderer;
  /**
   * What prints over every page. Default: the shell's page number ("Page N / total"). `false` or
   * `null`: nothing, for templates that number their own pages.
   */
  renderOverlay?: false | null | ((args: { pageNo: number; total: number; pageId: string; parent?: PageItem }) => React.ReactNode);
  renderPage?: (args: { page: StandalonePage & { pageNum: number }; parent?: PageItem }) => React.ReactNode;
  menuItems?: React.ReactNode;
  gridColsClass?: string;
  /** Reorder dialog heading; default: the shell's own, in its language. */
  reorderTitle?: LocalizedText;
  reorderDescription?: LocalizedText;
  stateKey?: string;
  onItemsChange?: (items: PageItem[], state: PageEditorState) => void;
  onStateChange?: (state: PageEditorState) => void;
  resolveNewItem?: (draft: PageItem) => Promise<PageItem | null | void> | PageItem | null | void;
  pageFilter?: PageFilterConfig; // Filter which pages to render
  printConfigs?: PrintConfigMap; // Unified print configurations (includes filter + pageFormat)
  /**
   * Initial preview zoom preference. Defaults to `fit-page` so a document opens with a whole
   * sheet visible; fit keeps following layout until the author picks a manual zoom.
   */
  defaultZoomMode?: DefaultZoomMode;
  /**
   * The corner the floating toolbar (page count, Add, Reorder, document options, zoom) starts in.
   * Default `bottom-right`. A user moves it from the zoom menu; their choice is remembered in the
   * browser and wins over this one.
   */
  toolbarPosition?: ToolbarPosition;
  // Dev-only brand-kit switcher (rendered in the DEV dropdown when devtools are enabled). The host
  // supplies the kit list + apply handler; PageEditor stays brand-kit agnostic.
  brandKits?: BrandKitOption[];
  activeBrandKitId?: string;
  onSelectBrandKit?: (id: string) => void;
  onAddBrandKit?: (input: string) => void;
}

function ItemAddedDialog({ label, onDone, onAddAnother }: { label: string | null; onDone: () => void; onAddAnother: () => void }) {
  const { t } = useShellTranslation();
  if (!label) return null;
  return (
    <div className="uhuu:fixed uhuu:inset-0 uhuu:z-50 uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-black/30">
      <div data-uhuu-editor className="uhuu:bg-(--uhuu-shell-surface) uhuu:rounded-lg uhuu:border uhuu:border-gray-200/80 uhuu:shadow-xl uhuu:p-6 uhuu:w-full uhuu:max-w-sm uhuu:mx-4 uhuu:flex uhuu:flex-col uhuu:items-center uhuu:text-center">
        <div className="uhuu:rounded-full uhuu:bg-emerald-100 uhuu:p-3 uhuu:mb-4">
          <Check className="uhuu:h-6 uhuu:w-6 uhuu:text-emerald-600" strokeWidth={2.5} />
        </div>
        <h2 className="uhuu:text-base uhuu:font-medium uhuu:text-gray-900 uhuu:mb-5">
          {t('addDialog.added', { name: label })}
        </h2>
        <div className="uhuu:flex uhuu:gap-2 uhuu:w-full">
          <Button variant="outline" size="sm" onClick={onAddAnother} className="uhuu:flex-1">
            {t('addDialog.addAnother')}
          </Button>
          <Button variant="default" size="sm" onClick={onDone} className="uhuu:flex-1">
            {t('addDialog.done')}
          </Button>
        </div>
      </div>
    </div>
  );
}

type PageEditorInnerProps = Omit<PageEditorProps, 'templateConfig'> & {
  /** `templateConfig.pageManagement`, resolved. */
  pageManagement?: ResolvedPageManagement;
  initialItems?: PageItem[];
  availableItems?: AvailableItem[];
  pageComponents?: { [pageId: string]: PageComponent };
  /** `templateConfig.spine.component` — artwork for the outer cover sheet's spine strip. */
  spineComponent?: SpineComponent;
};

// Cover spread developer warnings are emitted once per message per session.
const warnedCoverSpread = new Set<string>();

function PageEditorInner({
  initialItems = [],
  availableItems = [],
  pageComponents = {},
  spineComponent: SpineComponent,
  payload,
  pageFormat,
  pageOptions = [],
  notifyError,
  referenceRenderer,
  renderOverlay,
  renderPage,
  menuItems,
  gridColsClass,
  reorderTitle,
  reorderDescription,
  stateKey = DEFAULT_PAGE_EDITOR_STATE_KEY,
  onItemsChange,
  onStateChange,
  resolveNewItem,
  pageFilter,
  printConfigs,
  defaultZoomMode = 'fit-page',
  toolbarPosition,
  brandKits,
  activeBrandKitId,
  onSelectBrandKit,
  onAddBrandKit,
  pageManagement = FREE_PAGE_MANAGEMENT,
}: PageEditorInnerProps) {
  const [flowReadiness] = useState(() => paginationReadiness.createScope());
  // Which page-management controls this template allows (templateConfig.pageManagement).
  const controls = pageManagement;
  const setup = pageFormat ?? DEFAULT_PAGE_FORMAT;
  const { interactive, setInteractive, enableDevTools } = useInteractive();
  const shouldWarn = useDiagnosticWarnings();
  const shouldHideUI = useShouldHideUI();
  const { portalContainer } = usePortalRoot();
  const shellI18n = useShellTranslation();
  const { t, localize } = shellI18n;
  
  // Dev print mode state
  const [devFilter, setDevFilter] = useState<PageFilterConfig | null>(null);
  const [devPageFormat, setDevPageFormat] = useState<any>(null);
  const [devSelectedMode, setDevSelectedMode] = useState<string | undefined>(undefined);
  const [devModeTick, setDevModeTick] = useState(0);
  const [devReferenceOpacity, setDevReferenceOpacity] = useState(0);
  
  // Use devFilter if set, otherwise use pageFilter prop
  const effectiveFilter = devFilter ?? pageFilter;
  
  // Apply dev pageFormat overrides if set, otherwise use original pageFormat
  const effectivePageFormat = useMemo(() => {
    if (devPageFormat) {
      return { ...setup, ...devPageFormat };
    }
    return setup;
  }, [setup, devPageFormat]);
  
  // Get payload from context if available (preferred), otherwise use prop
  const templateDataContext = useContext(TemplateDataContext);
  const effectivePayload = templateDataContext?.payload ?? payload;
  const [orderDialogOpen, setOrderDialogOpen] = useState(false);

  // Perfect-binding cover spread: only a candidate while the cover filter is active AND
  // the editor is in export mode — a spread is a printer layout, not an editing surface
  // (page controls, thumbnails and reorder stay single-page). Decided before flow
  // measurement (needs no page list) so the flow layout key and every single-page render
  // can use a binding-less setup. The final plan is resolved from the rendered pages below.
  const coverSpreadCandidate = !interactive && isCoverSpreadCandidate(effectivePageFormat, effectiveFilter);
  const requestedPreview: PreviewMode = effectivePageFormat?.preview ?? 'single_page';
  const preview: PreviewMode = coverSpreadCandidate ? 'single_page' : requestedPreview;
  // Single-page setup: what every ordinary sheet renders with (never carries `binding`).
  const pageSetup = useMemo(() => {
    const base = omitBinding(effectivePageFormat);
    return requestedPreview === 'two_pages' || coverSpreadCandidate ? { ...base, preview: 'single_page' } : base;
  }, [requestedPreview, coverSpreadCandidate, effectivePageFormat]);
  const plainSetup = useMemo(() => omitBinding(setup), [setup]);

  const normalizedItems = useMemo(() => normalizePageItems(initialItems), [initialItems]);
  const resolvedPageOptions = useMemo(() => {
    if (!pageOptions?.length) return [];

    return pageOptions
      .map((option) => {
        if ('getValue' in option) return option;

        if (!templateDataContext?.setPageOptionValue) {
          if (shouldWarn) {
            console.warn(
              'PageEditor: payload-backed pageOptions require TemplateDataProvider or payload/onPayloadChange.'
            );
          }
          return null;
        }

        return buildPayloadPageOption(
          option,
          templateDataContext.payload,
          templateDataContext.setPageOptionValue
        );
      })
      .filter(Boolean) as PageOption[];
  }, [pageOptions, templateDataContext, shouldWarn]);

  const [lastAddedItem, setLastAddedItem] = useState<AvailableItem | null>(null);
  const [pendingInsertPosition, setPendingInsertPosition] = useState<InsertPosition>({ mode: 'end' });
  const [lastInsertedId, setLastInsertedId] = useState<string | null>(null);
  const highlightTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const {
    items,
    itemsWithPageNum,
    availableItemsToAdd,
    addItem,
    removeItem,
    reorderItems,
    updateItemFields,
    addDialogOpen,
    setAddDialogOpen,
    openAddDialog,
    itemsForReorder,
    handleReorder,
  } = usePageGroups({
    initialItems: normalizedItems,
    availableItems,
    payload: effectivePayload,
    stateKey,
    onItemsChange,
    onStateChange,
    resolveNewItem,
    notifyError,
  });

  // The same renderer draws both add and reorder cards; payload changes rebuild one factory.
  const defaultRenderThumbnail = useMemo(() => createDefaultRenderThumbnail({
    pageComponents, payload: effectivePayload, setup: pageSetup, i18n: shellI18n,
  }), [pageComponents, effectivePayload, pageSetup, shellI18n]);

  type LogicalPageWithParent = LogicalFlowPage;
  type VirtualPageWithParent = VirtualFlowPage<LogicalPageWithParent>;

  const logicalPages = useMemo<LogicalPageWithParent[]>(() => {
    const pages: LogicalPageWithParent[] = [];

    for (const item of itemsWithPageNum) {
      const itemPages = isPageGroup(item)
        ? (item.pages ?? []) as Array<StandalonePage & { pageNum: number }>
        : [item as StandalonePage & { pageNum: number }];

      for (const page of itemPages) {
        if (!page?.id) continue;
        const parentGroup = isPageGroup(item) ? item : undefined;
        pages.push({
          ...page,
          kind: 'page' as const,
          id: page.id,
          pageNum: page.pageNum ?? pages.length + 1,
          basePageNum: page.pageNum ?? pages.length + 1,
          parentGroup,
          flowKey: getPageFlowKey(page, parentGroup),
        });
      }
    }

    return pages.sort((a, b) => (a.basePageNum ?? 0) - (b.basePageNum ?? 0));
  }, [itemsWithPageNum]);

  const flowLayoutKey = useMemo(() => JSON.stringify({
    format: pageSetup?.format,
    orientation: pageSetup?.orientation,
    width: pageSetup?.width,
    height: pageSetup?.height,
    bleed: pageSetup?.bleed,
    showBleed: pageSetup?.showBleed,
    preview: pageSetup?.preview,
    flowPages: logicalPages
      .filter((page) => page.hasFlow)
      .map((page) => page.flowKey)
      .join('|'),
  }), [pageSetup, logicalPages]);

  const logicalTotalPageCount = useMemo(() => getTotalPageCount(items), [items]);

  const {
    committedFlowLayouts,
    allVirtualPages,
    renderedVirtualPages,
    virtualTotalPageCount,
    registerMeasurement: handleFlowMeasurement,
    pruneMeasurements: handleFlowPrune,
  } = useFlowLayouts<LogicalPageWithParent>({
    logicalPages,
    pageFilter: effectiveFilter,
    layoutKey: flowLayoutKey,
  });

  // Readiness lifecycle: every commit reports the flow pages and plans React rendered (the scope
  // ignores a commit that changes neither); hiding the tree (Suspense) invalidates it; only an
  // actual unmount disposes the scope.
  useIsoLayoutEffect(() => {
    flowReadiness.commit(logicalPages.filter((page) => page.hasFlow).map((page) => page.flowKey), committedFlowLayouts);
  });
  useIsoLayoutEffect(() => () => flowReadiness.suspend(), [flowReadiness]);
  React.useEffect(() => () => flowReadiness.unmount(), [flowReadiness]);

  const renderedVirtualPageIds = useMemo(
    () => new Set(renderedVirtualPages.map((page) => page.virtualPageId)),
    [renderedVirtualPages]
  );

  // Resolve the cover spread from the rendered (filtered, flow-expanded) pages.
  const coverSpread = useMemo(
    () => resolveCoverSpreadLayout({
      pageFormat: coverSpreadCandidate ? effectivePageFormat : omitBinding(effectivePageFormat),
      pageFilter: effectiveFilter,
      pages: renderedVirtualPages,
    }),
    [coverSpreadCandidate, effectivePageFormat, effectiveFilter, renderedVirtualPages]
  );
  const coverPlan = coverSpread.active ? coverSpread.plan : null;
  // Setup for the cover sheets: carries the binding so Pagination publishes the wide
  // sheet as the `@page` size. Every rendered sheet uses it while a spread is active,
  // so the root vars never flip between sizes.
  const spreadSetup = useMemo(
    () => (coverPlan ? { ...pageSetup, binding: coverSpread.setup.binding } : pageSetup),
    [coverPlan, pageSetup, coverSpread.setup]
  );

  React.useEffect(() => {
    if (!coverSpread.warnings.length) return;
    for (const warning of coverSpread.warnings) {
      if (warnedCoverSpread.has(warning)) continue;
      warnedCoverSpread.add(warning);
      console.warn(`[uhuu-components] PageEditor cover spread: ${warning}`);
    }
  }, [coverSpread.warnings]);

  const measurementOnlyPages = useMemo(
    () => allVirtualPages.filter((page) => (
      page.hasFlow &&
      page.virtualPageIndex === 0 &&
      // Cover spread panels render in `content` mode without their own measurement pass.
      (renderPage || !!coverPlan || !renderedVirtualPageIds.has(page.virtualPageId))
    )),
    [allVirtualPages, renderedVirtualPageIds, renderPage, coverPlan]
  );

  // Scroll to newly inserted page after layout settles (Section uses ResizeObserver
  // to calculate scaled height, so the DOM exists immediately but has correct
  // dimensions only after a short delay).
  React.useEffect(() => {
    if (!lastInsertedId) return;
    const timer = setTimeout(() => {
      const el = document.querySelector(`[data-page-item-id="${lastInsertedId}"]`);
      el?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 300);
    return () => clearTimeout(timer);
  }, [lastInsertedId]);

  const buildPageItemActionHandlers = usePageItemActions({
    items,
    reorderItems,
    availableItemsToAdd,
    setPendingInsertPosition,
    openAddDialog,
  });
  const buildItemActionHandlers: typeof buildPageItemActionHandlers = (topItem, anchorId) => {
    const handlers = buildPageItemActionHandlers(topItem, anchorId);
    return {
      onAddPage: controls.add ? handlers.onAddPage : undefined,
      onMoveUp: controls.reorder ? handlers.onMoveUp : undefined,
      onMoveDown: controls.reorder ? handlers.onMoveDown : undefined,
      onDuplicate: controls.duplicate ? handlers.onDuplicate : undefined,
    };
  };

  const handleAddItem = useCallback(async (item: AvailableItem) => {
    const result = await addItem(item, pendingInsertPosition);
    if (!result.success) return;

    setLastInsertedId(result.insertedId);
    if (highlightTimerRef.current) clearTimeout(highlightTimerRef.current);
    highlightTimerRef.current = setTimeout(() => setLastInsertedId(null), 1200);

    setPendingInsertPosition({ mode: 'end' });

    if (item.repeatable && item.integration) {
      setLastAddedItem(item);
    }
  }, [addItem, pendingInsertPosition]);

  const getMostVisiblePage = useCallback((): InsertPosition => {
    const pageEls = Array.from(document.querySelectorAll<HTMLElement>('[data-page-item-id]'));
    if (!pageEls.length) return { mode: 'end' };
    const viewportCenter = window.innerHeight / 2;
    let closest: HTMLElement | null = null;
    let closestDist = Infinity;
    for (const el of pageEls) {
      const rect = el.getBoundingClientRect();
      const dist = Math.abs((rect.top + rect.height / 2) - viewportCenter);
      if (dist < closestDist) { closestDist = dist; closest = el; }
    }
    const itemId = closest?.getAttribute('data-page-item-id');
    return itemId ? { mode: 'after', anchorId: itemId } : { mode: 'end' };
  }, []);

  const handleOpenAddDialogFromToolbar = useCallback(() => {
    setPendingInsertPosition(getMostVisiblePage());
    openAddDialog();
  }, [getMostVisiblePage, openAddDialog]);

  const handlePageOptionChange = React.useCallback(
    (pageOption: PageOption, targetItem: PageItem | undefined, value: string) => {
      if (!targetItem) return;

      const patch = pageOption.applyPatch?.(value, targetItem);
      if (patch) {
        updateItemFields(targetItem.id, patch);
      }

      pageOption.onChange?.(targetItem.id, value, {
        item: targetItem,
        updateItem: (patch) => updateItemFields(targetItem.id, patch),
      });
    },
    [updateItemFields]
  );

  const defaultOverlay = (info: { pageNo: number; total: number }) => (
    <div className="uhuu-page-overlay">
      <span>Page</span>
      <span>
        {info.pageNo} / {info.total}
      </span>
    </div>
  );

  const buildOverlay = (pageNo: number, pageId: string, parent?: PageItem) => {
    if (renderOverlay === false || renderOverlay === null) return null;
    if (renderOverlay) {
      return renderOverlay({ pageNo, total: virtualTotalPageCount, pageId, parent });
    }
    return defaultOverlay({ pageNo, total: virtualTotalPageCount });
  };

  const renderPageContent = (
    page: VirtualPageWithParent,
    options: { renderVisible?: boolean; measureFlow?: boolean; renderMode?: 'sheet' | 'content'; spread?: SpreadInfo } = {}
  ) => {
    const parent = page.parentGroup;

    // A custom `renderPage` produces whole sheets; cover spread panels need bare content.
    if (renderPage && options.renderVisible !== false && options.renderMode !== 'content') {
      return renderPage({ page, parent });
    }

    const componentKey = page.componentKey ?? page.id;
    const reference = enableDevTools && referenceRenderer ? referenceRenderer(page) : null;
    const effectiveReference =
      enableDevTools && referenceRenderer
        ? (
            React.isValidElement(reference)
              ? React.cloneElement(reference as React.ReactElement<any>, {
                  opacity: devReferenceOpacity,
                })
              : reference
          )
        : null;
    const templateId = page.templateId ?? componentKey;
    const PageComponent = pageComponents[componentKey];
    const pagePayload = templateDataContext?.getPagePayload
      ? templateDataContext.getPagePayload(page)
      : resolvePagePayload(effectivePayload, { id: page.id, templateId, componentKey });
    
    // Resolve integration data using utility function
    // For group pages, prefer parent group's integration; fallback to page's own integration
    const integration = resolveIntegrationForPage(
      effectivePayload,
      page,
      parent
    );

    const dataBinding = buildPageDataBinding({
      payload: effectivePayload,
      page,
      parentGroup: parent,
      pagePayload,
    });

    return (
      <PageCanvas
        key={`${options.renderVisible === false ? 'measure-only' : 'page'}-${page.virtualPageId}`}
        pageId={page.id}
        templateId={templateId}
        pageNo={page.pageNum}
        measurementPageNo={page.basePageNum}
        component={PageComponent}
        payload={effectivePayload}
        pagePayload={pagePayload}
        integration={integration}
        page={page}
        parentGroup={parent}
        componentKey={componentKey}
        setup={spreadSetup}
        reference={effectiveReference}
        overlay={({ pageNo }) => buildOverlay(pageNo, page.id, parent)}
        className={page.className}
        dataBinding={dataBinding}
        totalPages={virtualTotalPageCount}
        measurementTotalPages={logicalTotalPageCount}
        flowPageIndex={page.virtualPageIndex}
        flowChunksByFlowId={page.flowChunksByFlowId}
        measureFlow={options.measureFlow ?? (!!page.hasFlow && page.virtualPageIndex === 0)}
        flowMeasurementKey={page.flowKey}
        flowMeasurementVersion={flowLayoutKey}
        flowReadiness={flowReadiness}
        onFlowMeasurement={page.hasFlow ? handleFlowMeasurement : undefined}
        onFlowPrune={handleFlowPrune}
        renderVisible={options.renderVisible ?? true}
        renderMode={options.renderMode}
        spread={options.spread}
      />
    );
  };

  const panelClassName = (page: VirtualPageWithParent) => {
    const key = page.componentKey ?? page.templateId ?? page.id;
    return [key ? `uhuu-page--${key}` : '', page.className].filter(Boolean).join(' ');
  };

  /** One physical cover sheet: two page panels around the spine (see docs/printer-cover-spine-support.md §6). */
  const renderCoverSheet = (sheet: NonNullable<typeof coverPlan>['sheets'][number]) => {
    if (!coverPlan) return null;
    const { binding, page: pageGeometry } = coverPlan;
    const [leftPanel, rightPanel] = sheet.panels;
    const left = leftPanel.page as VirtualPageWithParent;
    const right = rightPanel.page as VirtualPageWithParent;
    const spreadFor = (side: 'left' | 'right'): SpreadInfo => ({
      sheet: sheet.sheet,
      side,
      spine: binding.spine,
      glue: binding.glue,
      bleed: pageGeometry.bleed,
    });
    const title = `Cover sheet ${sheet.index + 1} · ${sheet.sheet} (pages ${left.pageNum} + ${right.pageNum})`;

    return (
      <div key={`cover-sheet-${sheet.sheet}`} data-page-item-id={right.parentGroup?.id ?? right.id}>
        <Section
          title={title}
          controls={(
            <div data-uhuu-editor className="uhuu:pl-0 uhuu:pr-3 uhuu:py-1.5 uhuu:flex uhuu:items-center uhuu:gap-2 uhuu:h-9">
              <span className="uhuu-page-number">{left.pageNum} + {right.pageNum}</span>
              <span className="uhuu:text-xs uhuu:text-gray-500">{title}</span>
            </div>
          )}
        >
          <Pagination setup={spreadSetup}>
            <CoverSpread
              sheet={sheet.sheet}
              pageNo={[left.pageNum, right.pageNum]}
              left={renderPageContent(left, { renderMode: 'content', spread: spreadFor('left') })}
              right={renderPageContent(right, { renderMode: 'content', spread: spreadFor('right') })}
              spine={SpineComponent && sheet.sheet === 'outer' ? (
                <SpineComponent
                  payload={effectivePayload}
                  sheet="outer"
                  spine={binding.spine}
                  glue={binding.glue}
                  bleed={pageGeometry.bleed}
                  height={pageGeometry.height}
                  totalPages={virtualTotalPageCount}
                  pages={{ left, right }}
                />
              ) : undefined}
              overlay={({ pageNo, side }) => {
                const target = side === 'left' ? left : right;
                return buildOverlay(pageNo, target.id, target.parentGroup);
              }}
              leftClassName={panelClassName(left)}
              rightClassName={panelClassName(right)}
              leftPageKey={left.componentKey ?? left.templateId ?? left.id}
              rightPageKey={right.componentKey ?? right.templateId ?? right.id}
            />
          </Pagination>
        </Section>
      </div>
    );
  };

  // Render controls for standalone pages or group pages
  const renderPageControls = (
    page: VirtualPageWithParent,
    parentGroup?: PageItem,
    actionHandlers?: {
      onAddPage?: () => void;
      onMoveUp?: () => void;
      onMoveDown?: () => void;
      onDuplicate?: () => void;
    }
  ) => {
    const isGroupPage = !!parentGroup && isPageGroup(parentGroup);
    const isFirstPageInGroup = isGroupPage && parentGroup.pages[0]?.id === page.id;

    if (page.virtualPageIndex > 0) {
      return (
        <div data-uhuu-editor className="uhuu:pl-0 uhuu:pr-3 uhuu:py-1.5 uhuu:flex uhuu:items-center uhuu:gap-2 uhuu:h-9">
          <span className="uhuu-page-number">{page.pageNum}</span>
          <span className="uhuu:text-xs uhuu:text-gray-500">
            {t('page.continued', { name: localize(page.label) || page.componentKey || page.id })}
          </span>
        </div>
      );
    }

    // For group pages, only show controls on the first page (group-level controls)
    if (isGroupPage && !isFirstPageInGroup) {
      return (
        <div data-uhuu-editor className="uhuu:pl-0 uhuu:pr-3 uhuu:py-1.5 uhuu:flex uhuu:justify-between uhuu:items-center uhuu:h-9">
          <div className="uhuu:flex uhuu:items-center uhuu:gap-2">
            <span className="uhuu-page-number">
              {page.pageNum}
            </span>
            {page.label && (
              <span className="uhuu:text-xs uhuu:text-gray-500">
                {localize(page.label)}
              </span>
            )}
            <span className="uhuu:text-xs uhuu:text-gray-400">·</span>
          </div>
        </div>
      );
    }

    const targetItem = isGroupPage ? parentGroup : page;
    const displayName = isGroupPage
      ? (localize(parentGroup.label) || parentGroup.id)
      : (localize(page.label) || t('page.fallbackName', { number: page.pageNum }));

    // Group-level controls (for first page in group) or standalone page controls
    return (
      <div data-uhuu-editor className="uhuu:pl-0 uhuu:flex uhuu:items-center uhuu:h-9">
        <span className="uhuu-page-number uhuu:shrink-0 uhuu:text-xs uhuu:tabular-nums uhuu:text-gray-400 uhuu:font-medium uhuu:pr-1">{page.pageNum}</span>
        <PageNameDropdown
          name={displayName}
          canRename={controls.rename}
          canMoveUp={!!actionHandlers?.onMoveUp}
          canMoveDown={!!actionHandlers?.onMoveDown}
          canAddPage={!!actionHandlers?.onAddPage}
          canDuplicate={!!actionHandlers?.onDuplicate}
          canDelete={controls.remove && logicalTotalPageCount > 1}
          onRename={(val) => updateItemFields(targetItem.id, { label: val || undefined })}
          onMoveUp={actionHandlers?.onMoveUp}
          onMoveDown={actionHandlers?.onMoveDown}
          onAddPage={actionHandlers?.onAddPage}
          onDuplicate={actionHandlers?.onDuplicate}
          onDelete={() => removeItem(targetItem.id)}
        />
        <span className="uhuu:pl-1">
        {resolvedPageOptions.length > 0 && (
          <PageOptionsDropdown
            pageOptions={resolvedPageOptions}
            targetItem={targetItem}
            onChange={handlePageOptionChange}
            title={isGroupPage ? t('page.groupOptions') : t('page.options')}
          />
        )}
        </span>
      </div>
    );
  };

  type PagePair = {
    left?: VirtualPageWithParent;
    right?: VirtualPageWithParent;
    layout: "spread" | "left" | "right";
  };

  /**
   * Transform origin logic for two-page spreads:
   * - Even pages (2,4,6...) appear on LEFT side → scale from RIGHT edge (gutter)
   * - Odd pages (1,3,5...) appear on RIGHT side → scale from LEFT edge (gutter)
   * This ensures pages meet precisely at center when zoomed
   */
  const pagePairs = useMemo<PagePair[]>(() => {
    if (preview !== 'two_pages') return [];

    const pages = renderedVirtualPages;
    if (!pages.length) return [];
    
    // Page 1 is always alone on the right (cover)
    const pairs: PagePair[] = [{ left: undefined, right: pages[0], layout: "right" }];
    
    // Subsequent pages are paired: 2-3, 4-5, 6-7, etc.
    for (let i = 1; i < pages.length; i += 2) {
      const leftPage = pages[i];
      const rightPage = pages[i + 1];
      
      if (rightPage) {
        pairs.push({ left: leftPage, right: rightPage, layout: "spread" });
      } else {
        // Single page at end: even pages go left, odd pages go right
        const isEven = leftPage.pageNum % 2 === 0;
        pairs.push({
          left: isEven ? leftPage : undefined,
          right: isEven ? undefined : leftPage,
          layout: isEven ? "left" : "right",
        });
      }
    }
    
    return pairs;
  }, [preview, renderedVirtualPages]);

  const defaultMenu = (
    <div className="uhuu:flex uhuu:items-center uhuu:gap-1">
      <Badge variant="secondary" className="uhuu:font-normal uhuu:text-xs uhuu:bg-gray-100/80 uhuu:text-gray-700 uhuu:border-0">
        {t('toolbar.pages', { count: virtualTotalPageCount })}
      </Badge>
      { enableDevTools && (
        <DevPrintControls
          modes={printConfigs}
          selectedMode={devSelectedMode}
          onModeChange={(mode, config) => {
            setDevSelectedMode(mode);
            setDevFilter(config.filter ?? null);
            setDevPageFormat(config.pageFormat ?? null);
            setDevModeTick((v) => v + 1);
          }}
          interactive={interactive}
          onInteractiveChange={(newInteractive) => {
            setInteractive(newInteractive);
            // Reset pageFormat overrides when going back to edit mode
            if (newInteractive) {
              setDevPageFormat(null);
            }
          }}
          hasReferenceRenderer={!!referenceRenderer}
          referenceOpacity={devReferenceOpacity}
          onReferenceOpacityChange={setDevReferenceOpacity}
          brandKits={brandKits}
          activeBrandKitId={activeBrandKitId}
          onSelectBrandKit={onSelectBrandKit}
          onAddBrandKit={onAddBrandKit}
        />
      )}      
      {interactive && (
        <>
          {controls.add && availableItemsToAdd.length > 0 && (
          <Button
            variant="ghost"
            size="sm"
            onClick={handleOpenAddDialogFromToolbar}
            title={t('toolbar.addHint')}
            className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-700 uhuu:hover:bg-gray-100/80 uhuu:h-7 uhuu:px-2.5"
          >
            <Plus className="uhuu:w-3.5 uhuu:h-3.5" />
            {t('toolbar.add')}
          </Button>
          )}
          {controls.reorder && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setOrderDialogOpen(true)}
            title={t('toolbar.reorderHint')}
            className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-700 uhuu:hover:bg-gray-100/80 uhuu:h-7 uhuu:px-2.5"
          >
            <ClipboardList className="uhuu:w-3.5 uhuu:h-3.5" />
            {t('toolbar.reorder')}
          </Button>
          )}
        </>
      )}
    </div>
  );

  return (
    <>
      {measurementOnlyPages.map((page) => (
        renderPageContent(page, {
          renderVisible: false,
          measureFlow: true,
        })
      ))}

      {/* Back button when in print mode - always rendered, hidden in print output. Portaled:
          print mode drops data-uhuu-interactive, and the shell's styles are scoped to it. */}
      {enableDevTools && !interactive && portalContainer && createPortal(
        <Button
          onClick={() => {
            setInteractive(true);
            // Same reset as the dev dropdown's "Edit" entry: print-mode page format
            // overrides (bleed, binding) must not leak into the editing surface.
            setDevPageFormat(null);
          }}
          data-uhuu-editor
          size="sm"
          className="uhuu-screen-only uhuu:fixed uhuu:top-4 uhuu:right-4 uhuu:z-50 uhuu:flex uhuu:items-center uhuu:gap-1.5 uhuu:text-xs! uhuu:rounded-full"
          title="Back to Edit Mode"
        >
          <X className="uhuu:w-4 uhuu:h-4" />
          Back to Editor
        </Button>,
        portalContainer
      )}
      
      <SectionPageResizer
        key={`dev-mode-${devModeTick}-${devSelectedMode ?? 'default'}`}
        defaultZoom={80}
        defaultZoomMode={defaultZoomMode}
        toolbarPosition={toolbarPosition}
        minZoom={25}
        maxZoom={200}
        menuItems={menuItems ?? defaultMenu}
        onAddPage={controls.add ? handleOpenAddDialogFromToolbar : undefined}
        preview={preview}
      >
        {coverPlan ? (
          coverPlan.sheets.map(renderCoverSheet)
        ) : preview === 'two_pages' ? (
          pagePairs.map((pair, index) => {
            // Anchor IDs for insert position (before = first item in pair, after = last item)
            const firstPage = pair.left ?? pair.right;
            const lastPage = pair.right ?? pair.left;
            const firstAnchorId = (firstPage?.parentGroup as any)?.id ?? firstPage?.id ?? null;
            const lastAnchorId = (lastPage?.parentGroup as any)?.id ?? lastPage?.id ?? null;

            // Highlight if either page in the pair was just inserted
            const leftTopId = (pair.left?.parentGroup as any)?.id ?? pair.left?.id;
            const rightTopId = (pair.right?.parentGroup as any)?.id ?? pair.right?.id;
            const isLeftHighlighted = leftTopId === lastInsertedId;
            const isRightHighlighted = rightTopId === lastInsertedId;

            const getPageHandlers = (page: VirtualPageWithParent | undefined, anchorId: string | null) =>
              buildItemActionHandlers(page ? (page.parentGroup ?? page) as PageItem : undefined, anchorId);

            return (
              <TwoPageSection key={`pair-${index}`} layout={pair.layout} pageItemId={lastAnchorId ?? undefined}>
                {pair.left && (
                  <div
                    data-page-item-id={pair.left.virtualPageIndex === 0 ? leftTopId : undefined}
                    className={isLeftHighlighted ? 'uhuu:outline uhuu:outline-2 uhuu:outline-offset-2 uhuu:outline-blue-100 uhuu:bg-blue-50' : undefined}
                  >
                    <Section
                      key={pair.left.virtualPageId}
                      title={`Sheet ${pair.left.pageNum}`}
                      controls={renderPageControls(pair.left, pair.left.parentGroup, getPageHandlers(pair.left, firstAnchorId))}
                      origin={pair.left.pageNum % 2 === 0 ? 'right' : 'left'}
                    >
                      {renderPageContent(pair.left)}
                    </Section>
                  </div>
                )}
                {pair.right && (
                  <div
                    data-page-item-id={pair.right.virtualPageIndex === 0 ? rightTopId : undefined}
                    className={isRightHighlighted ? 'uhuu:outline uhuu:outline-2 uhuu:outline-offset-2 uhuu:outline-blue-100 uhuu:bg-blue-50' : undefined}
                  >
                    <Section
                      key={pair.right.virtualPageId}
                      title={`Sheet ${pair.right.pageNum}`}
                      controls={renderPageControls(pair.right, pair.right.parentGroup, getPageHandlers(pair.right, lastAnchorId))}
                      origin={pair.right.pageNum % 2 === 0 ? 'right' : 'left'}
                    >
                      {renderPageContent(pair.right)}
                    </Section>
                  </div>
                )}
              </TwoPageSection>
            );
          })
        ) : (
          renderedVirtualPages.map((page) => {
            const targetItem = (page.parentGroup ?? page) as PageItem;
            const anchorId = page.parentGroup?.id ?? page.id;
            const actionHandlers = buildItemActionHandlers(targetItem, anchorId);
            const topId = page.parentGroup?.id ?? page.id;
            const isHighlighted = lastInsertedId === topId;

            return (
              <div
                key={page.virtualPageId}
                data-page-item-id={page.virtualPageIndex === 0 ? topId : undefined}
                className={isHighlighted ? 'uhuu:outline uhuu:outline-2 uhuu:outline-offset-2 uhuu:outline-blue-100 uhuu:bg-blue-50' : undefined}
              >
                <Section
                  title={`Sheet ${page.pageNum}`}
                  controls={renderPageControls(page, page.parentGroup, actionHandlers)}
                >
                  {renderPageContent(page)}
                </Section>
              </div>
            );
          })
        )}
      </SectionPageResizer>

      {interactive && !shouldHideUI && (
        <>
          {controls.add && (
          <AddPageDialog
            open={addDialogOpen}
            onOpenChange={setAddDialogOpen}
            availableItems={availableItemsToAdd}
            renderThumbnail={defaultRenderThumbnail}
            onSelectItem={handleAddItem}
            payload={effectivePayload}
            setup={plainSetup}
            gridColsClass={gridColsClass}
            data-uhuu-editor
          />
          )}

          {controls.reorder && (
          <PageOrderDialog
            open={orderDialogOpen}
            onOpenChange={setOrderDialogOpen}
            pages={itemsForReorder}
            onReorder={(newOrder) => {
              handleReorder(newOrder);
              setOrderDialogOpen(false);
            }}
            onRemove={controls.remove ? (item) => removeItem(item.id) : undefined}
            pageComponents={pageComponents}
            payload={effectivePayload}
            setup={plainSetup}
            renderThumbnail={defaultRenderThumbnail}
            title={localize(reorderTitle) ?? t('reorderDialog.title')}
            description={localize(reorderDescription) ?? t('reorderDialog.description')}
            gridColsClass={gridColsClass}
            data-uhuu-editor
          />
          )}
        </>
      )}

      <ItemAddedDialog
        label={lastAddedItem ? (localize(lastAddedItem.label) ?? lastAddedItem.id) : null}
        onDone={() => setLastAddedItem(null)}
        onAddAnother={() => {
          const item = lastAddedItem;
          setLastAddedItem(null);
          if (item) handleAddItem(item);
        }}
      />
    </>
  );
}

function PageEditorView(props: PageEditorProps & Omit<PageEditorInnerProps, keyof PageEditorProps>) {
  const { templateConfig, ...rest } = props;
  // Check if TemplateDataProvider already exists in the tree
  const existingContext = useContext(TemplateDataContext);
  
  // If context exists, or if no payload/onPayloadChange is provided, render directly
  // Otherwise, wrap with TemplateDataProvider for automatic payload management
  if (existingContext || (!props.payload && !props.onPayloadChange)) {
    return <PageEditorInner {...rest} />;
  }
  
  // Wrap with TemplateDataProvider to enable automatic payload updates
  // Pass stateKey so it can preserve page editor state correctly
  return (
    <TemplateDataProvider 
      payload={props.payload} 
      onPayloadChange={props.onPayloadChange}
      stateKey={props.stateKey}
    >
      <PageEditorInner {...rest} />
    </TemplateDataProvider>
  );
}

const FREE_PAGE_MANAGEMENT = resolvePageManagement();

export function PageEditor(props: PageEditorProps) {
  const templateDataContext = useContext(TemplateDataContext);
  const { t } = useShellTranslation();
  const effectivePayload = templateDataContext?.payload ?? props.payload;
  
  // Evaluate config with current payload - this re-runs when payload changes
  const resolvedConfig = React.useMemo(
    () => buildPageGroupsConfig({ ...props.templateConfig, payload: effectivePayload }),
    [props.templateConfig, effectivePayload]
  );
  const spineComponent = (props.templateConfig as any)?.spine?.component as SpineComponent | undefined;
  
  const [noticeState, setNoticeState] = React.useState<{ open: boolean; message: string }>({
    open: false,
    message: '',
  });

  const notifyError = React.useCallback((message: string) => {
    setNoticeState({ open: true, message });
  }, []);

  // Read persisted state
  const restoredState = React.useMemo(
    // Read where usePageGroups writes: a custom `stateKey` was saved but never loaded.
    () => readPageEditorState(effectivePayload, props.stateKey ?? DEFAULT_PAGE_EDITOR_STATE_KEY),
    [effectivePayload, props.stateKey]
  );
  
  const pageManagement = React.useMemo(() => {
    const options = props.templateConfig.pageManagement;
    if (options != null && typeof options !== 'object') {
      console.warn(
        '[uhuu-components] templateConfig.pageManagement takes an object, e.g. { locked: true }; ' +
        `${JSON.stringify(options)} is ignored and every page-management control stays on.`
      );
    }
    return resolvePageManagement(options);
  }, [props.templateConfig.pageManagement]);

  const restoredItems = React.useMemo(() => restorePageEditorItems({
    initialItems: resolvedConfig.initialItems,
    savedItems: restoredState?.items,
    config: props.templateConfig,
    payload: effectivePayload,
    management: pageManagement,
  }), [restoredState?.items, resolvedConfig.initialItems, effectivePayload, props.templateConfig, pageManagement]);

  return (
    // PageEditor's own readiness scope covers every page it renders: their Pagination roots must
    // not publish standalone scopes.
    <PaginationReadinessOwnerContext.Provider value={true}>
      <PageEditorView
        {...props}
        payload={effectivePayload}
        initialItems={restoredItems}
        availableItems={pageManagement.add || pageManagement.duplicate ? resolvedConfig.availableItems : []}
        pageManagement={pageManagement}
        pageComponents={resolvedConfig.pageComponents}
        spineComponent={spineComponent}
        notifyError={notifyError}
      />

      <AlertDialog
        open={noticeState.open}
        onOpenChange={(open) => {
          if (!open) {
            setNoticeState({ open: false, message: '' });
          }
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('notice.cannotRemoveTitle')}</AlertDialogTitle>
            <AlertDialogDescription>
              {noticeState.message}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogAction onClick={() => setNoticeState({ open: false, message: '' })}>
              {t('notice.ok')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </PaginationReadinessOwnerContext.Provider>
  );
}

export default PageEditor;
