/**
 * Which page-management controls the editor shell offers (templateConfig.pageManagement).
 *
 * Shaped like a map API's UI options: `locked` is the master switch (every control off at once) and
 * each control key overrides it either way, so `{ locked: true, rename: true }` allows renaming
 * only and `{ add: false }` hides adding alone. A template re-evaluated with the payload can switch
 * them at runtime (a print product locks, the same template edited freely does not).
 *
 * When no control can change the page list (add, remove, reorder and duplicate all off) the
 * template owns it: a saved page order is ignored (`carrySavedSettings`). Pure, DOM-free.
 */
import { isTemplateLabel } from '../../i18n/i18n-core.js';

export const PAGE_MANAGEMENT_CONTROLS = ['add', 'remove', 'reorder', 'duplicate', 'rename'];

export function resolvePageManagement(options) {
  const config = options && typeof options === 'object' ? options : {};
  const fallback = config.locked !== true;
  const controls = Object.fromEntries(PAGE_MANAGEMENT_CONTROLS.map((control) => [
    control,
    typeof config[control] === 'boolean' ? config[control] : fallback,
  ]));
  return {
    ...controls,
    templateOwnsPages: !controls.add && !controls.remove && !controls.reorder && !controls.duplicate,
  };
}

// The fields of a page item that describe the template's page, as opposed to settings written onto
// it later (a page option's applyPatch).
const TEMPLATE_ITEM_FIELDS = new Set([
  'kind', 'id', 'pages', 'templateId', 'componentKey', 'dataKey', 'hasFlow', 'strictPosition',
  'label', 'className', 'repeatable', 'maxInstances', 'allowAsSinglePage', 'thumbnail',
]);

/**
 * The template's page list with what a locked list keeps from saved editor state: the settings page
 * options wrote onto an item, matched by id, and, when `rename` is allowed, a name the user gave an
 * item (a saved label that is the template's own is not a rename, so a template's current label,
 * per-language included, reaches documents saved earlier). Order, membership and the template's
 * own fields come from the template, so a list saved before the lock (or before the payload
 * changed) cannot rearrange it.
 */
export function carrySavedSettings(items, saved, { rename = false } = {}) {
  if (!saved?.length) return items;
  const savedById = new Map();
  const index = (list) => list.forEach((item) => {
    if (item?.id) savedById.set(item.id, item);
    if (Array.isArray(item?.pages)) index(item.pages);
  });
  index(saved);
  const merge = (item) => {
    const prior = savedById.get(item.id);
    const settings = prior
      ? Object.fromEntries(Object.entries(prior).filter(([key]) => !TEMPLATE_ITEM_FIELDS.has(key)))
      : {};
    if (prior && rename && !isTemplateLabel(prior.label, item.label)) settings.label = prior.label;
    const merged = { ...item, ...settings };
    return Array.isArray(item.pages) ? { ...merged, pages: item.pages.map(merge) } : merged;
  };
  return items.map(merge);
}
