    const generatedUrl = uploaded ?? failedUpload;
    const isGenerated = !!markerType || !!generatedUrl || nonEmptyString(value.dataImage) !== undefined;
    // On a generated shape `url` normally mirrors `image`; `contentUrl` is a pick on it.
