  if (!isFrameValue(value)) return normalizeLegacy(value, options);
  const record = sanitizeRecord(value[FRAME_KEY] as unknown as AnyRecord);
  // The editor mirrors the shown source's annotation to `annotationPath`. A different one there
  // was saved by an editor without frames (its `types` chooser offers the annotation at that
  // path): the newest write, so it becomes the layer.
