import { MoreHorizontal } from 'lucide-react';
import { Button } from '../../ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from '../../ui/dropdown-menu';
import { PageOption } from './page-editor';
import { PageItem } from './page-group-utils';
import { PageOptionsRenderer, getApplicablePageOptions } from './page-options-renderer';
import { useShellTranslation } from '../../i18n/locale-context';

export interface PageOptionsDropdownProps {
  pageOptions: PageOption[];
  targetItem: PageItem | undefined;
  onChange: (pageOption: PageOption, targetItem: PageItem, value: string) => void;
  title?: string;
  triggerClassName?: string;
}

export function PageOptionsDropdown({
  pageOptions,
  targetItem,
  onChange,
  title,
  triggerClassName,
}: PageOptionsDropdownProps) {
  const { t } = useShellTranslation();
  const resolvedTitle = title ?? t('page.optionsMenu');
  if (!targetItem) return null;
  if (getApplicablePageOptions(pageOptions, targetItem).length === 0) return null;

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild className={triggerClassName || 'uhuu-page-options-trigger'}>
        <Button
          variant="ghost"
          size="sm"
          className="uhuu:h-7 uhuu:w-7 uhuu:text-gray-400 uhuu:hover:text-gray-600 uhuu:border uhuu:border-transparent uhuu:hover:border-gray-200 uhuu:rounded-md"
          title={resolvedTitle}
        >
          <MoreHorizontal className="uhuu:w-3.5 uhuu:h-3.5" />
          <span className="uhuu:sr-only">{resolvedTitle}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        className="uhuu:w-64 uhuu:max-w-[calc(100vw-2rem)] uhuu:p-3"
        align="center"
        aria-label={resolvedTitle}
      >
        <p className="uhuu:mb-3 uhuu:text-sm uhuu:font-medium uhuu:text-gray-900">{resolvedTitle}</p>
        <PageOptionsRenderer
          pageOptions={pageOptions}
          targetItem={targetItem}
          onChange={onChange}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

